# owner: platform
"""Short text notices for parents about missed days."""

from typing import List

from rosterkit.models import Student, Mark
from rosterkit.errors import ProjectError


def _absent_days(student: Student, marks: List[Mark]) -> list:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(f"mark for {mark.student_id} given for {student.student_id}")
    return sorted(mark.day for mark in marks if mark.status == "absent")


# ---
def absence_notice(student: Student, marks: List[Mark]) -> str:
    """Build a notice naming the student, the count and the dates missed."""
    days = _absent_days(student, marks)
    if not days:
        raise ProjectError(f"no absences for {student.student_id}")
    dates = ", ".join(day.isoformat() for day in days)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {len(days)} day(s): {dates}."
